<?php namespace App\Models;use Illuminate\Database\Eloquent\Model;class Appointment extends Model{protected $fillable=['child_id','hospital_id','vaccine_id','appointment_date','appointment_time','status','admin_note','hospital_note'];protected $casts=['appointment_date'=>'date'];public function child(){return $this->belongsTo(Child::class);}public function hospital(){return $this->belongsTo(Hospital::class);}public function vaccine(){return $this->belongsTo(Vaccine::class);}}
